import { Motif } from '../types/motif';

export type RawMotif = Pick<Motif, 'id' | 'name' | 'embedding' | 'image_path' | 'tarot_index' | 'iching_hexagram_number' | 'chapter'>;

export function cosineSimilarity(a: number[], b: number[]): number {
  const len = Math.min(a.length, b.length);
  let dot = 0;
  let magA = 0;
  let magB = 0;
  for (let i = 0; i < len; i++) {
    const ai = a[i] || 0;
    const bi = b[i] || 0;
    dot += ai * bi;
    magA += ai * ai;
    magB += bi * bi;
  }
  const denom = Math.sqrt(magA) * Math.sqrt(magB) || 1;
  return dot / denom;
}

export function averageEmbeddings(vectors: number[][]): number[] | null {
  const valid = vectors.filter(v => Array.isArray(v) && v.length > 0);
  if (valid.length === 0) return null;
  const dim = valid[0].length;
  const avg = new Array(dim).fill(0);
  for (const v of valid) {
    for (let i = 0; i < dim; i++) avg[i] += v[i];
  }
  for (let i = 0; i < dim; i++) avg[i] /= valid.length;
  return avg;
}

export function findNearest(
  query: number[],
  motifs: RawMotif[],
  excludeIds: Set<string>
): { motif: RawMotif | null; similarity: number } {
  let best: RawMotif | null = null;
  let bestSim = -Infinity;
  for (const m of motifs) {
    if (excludeIds.has(m.id)) continue;
    const emb = m.embedding || [];
    if (!emb.length) continue;
    const sim = cosineSimilarity(query, emb);
    if (sim > bestSim) {
      bestSim = sim;
      best = m;
    }
  }
  return { motif: best, similarity: bestSim };
}

export function resolvePublicImagePath(imagePath?: string): string | null {
  if (!imagePath) return null;
  // Many dataset entries point to images/*.jpg. Our public assets are .png.
  const file = imagePath.split('/').pop() || '';
  const base = file.replace(/\.jpg$/i, '.png');
  const baseUrl = (process.env.PUBLIC_URL || '').replace(/\/$/, '');
  return `${baseUrl}/images/${base}`;
}


