import { Delaunay } from 'd3-delaunay';
import { MotifBeadManager } from './MotifBeadManager';
import { MotifBead } from './MotifBead';

type Rect = { x: number; y: number; w: number; h: number };

type VoronoiOptions = {
  padding?: number;
  colorMode?: 'jaccard' | 'avgdist';
  k?: number; // semantic neighbors for jaccard
  outline?: boolean;
  legend?: boolean;
  alpha?: number; // 0..1
};

export class VoronoiManager {
  private beadManager: MotifBeadManager;

  constructor() {
    this.beadManager = MotifBeadManager.getInstance();
  }

  private toItemRect(item: any): Rect {
    const w = typeof item.width === 'number' ? item.width : (item.bounds?.width ?? 0);
    const h = typeof item.height === 'number' ? item.height : (item.bounds?.height ?? 0);
    return { x: item.x, y: item.y, w, h };
  }

  private selectionBoundingBox(selection: any[]): Rect | null {
    if (!selection || selection.length === 0) return null;
    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    for (const it of selection) {
      const r = this.toItemRect(it);
      const left = r.x - r.w / 2;
      const right = r.x + r.w / 2;
      const top = r.y - r.h / 2;
      const bottom = r.y + r.h / 2;
      if (isFinite(left) && isFinite(right) && isFinite(top) && isFinite(bottom)) {
        if (left < minX) minX = left;
        if (right > maxX) maxX = right;
        if (top < minY) minY = top;
        if (bottom > maxY) maxY = bottom;
      }
    }
    if (!isFinite(minX) || !isFinite(maxX) || !isFinite(minY) || !isFinite(maxY)) return null;
    const w = Math.max(1, maxX - minX);
    const h = Math.max(1, maxY - minY);
    const x = minX + w / 2;
    const y = minY + h / 2;
    return { x, y, w, h };
  }

  private async selectionSitesFromBeads(selection: any[]): Promise<{
    sites: Array<{ x: number; y: number; bead: MotifBead }>;
    imageById: Map<string, any>;
  }> {
    // Collect group IDs and groupId fields from selection
    const groupIds = new Set<string>();
    for (const item of selection) {
      const type = (item as any).type;
      const id = (item as any).id;
      if (type === 'group' && id) groupIds.add(id);
      const gid = (item as any).groupId;
      if (gid) groupIds.add(gid);
    }

    const beads: MotifBead[] = [];
    for (const gid of Array.from(groupIds)) {
      const bead = this.beadManager.getBeadByGroupId(gid);
      if (bead) beads.push(bead);
    }

    if (beads.length === 0) return { sites: [], imageById: new Map() };

    // Fetch images to get their true center positions
    let images: any[] = [];
    try {
      images = await window.miro.board.get({ id: beads.map(b => b.getImageId()), type: 'image' });
    } catch { images = []; }
    const byId = new Map<string, any>();
    for (const img of images) byId.set(img.id, img);

    const sites: Array<{ x: number; y: number; bead: MotifBead }> = [];
    for (const bead of beads) {
      const img = byId.get(bead.getImageId());
      const cx = img?.x, cy = img?.y;
      if (typeof cx === 'number' && typeof cy === 'number') {
        sites.push({ x: cx, y: cy, bead });
      }
    }

    return { sites, imageById: byId };
  }

  // Overloads to aid TS inference from call sites
  async runVoronoiOnSelection(padding?: number): Promise<{ cells: number; pasted: boolean }>;
  async runVoronoiOnSelection(options?: VoronoiOptions): Promise<{ cells: number; pasted: boolean }>;
  async runVoronoiOnSelection(optionsOrPadding: number | VoronoiOptions = 0): Promise<{ cells: number; pasted: boolean }>{
    const opts: VoronoiOptions = typeof optionsOrPadding === 'number' ? { padding: optionsOrPadding } : (optionsOrPadding || {});
    const padding = opts.padding ?? 0;
    const colorMode = opts.colorMode ?? undefined; // undefined means white fill
    const k = Math.max(1, Math.min(50, opts.k ?? 5));
    const outline = opts.outline !== false; // default true
    const legend = opts.legend === true;
    const alpha = Math.max(0, Math.min(1, opts.alpha ?? 1));
    const selection = await window.miro.board.getSelection();
    if (!selection || selection.length === 0) {
      return { cells: 0, pasted: false };
    }

    const bbox = this.selectionBoundingBox(selection);
    if (!bbox) return { cells: 0, pasted: false };

    // Apply padding in board units
    const pad = Math.max(0, padding);
    const boardW = bbox.w + pad * 2;
    const boardH = bbox.h + pad * 2;
    const boardX = bbox.x;
    const boardY = bbox.y;

    const { sites } = await this.selectionSitesFromBeads(selection);
    if (!sites || sites.length < 2) {
      // Edge case: < 2 sites → place a white rectangle with dark border
      const shape = await window.miro.board.createShape({
        content: '',
        shape: 'rectangle',
        x: boardX,
        y: boardY,
        width: boardW,
        height: boardH,
        style: {
          fillColor: '#ffffff',
          borderColor: '#222222',
          borderWidth: 2,
        }
      });
      try { await shape.sendToBack(); } catch {}
      return { cells: 0, pasted: true };
    }

    // Map board units to canvas pixels with capping
    const maxDim = 2000; // cap to keep data URL reasonable
    const scale = Math.min(maxDim / boardW, maxDim / boardH, 2); // allow some upscaling, cap at 2x
    const canvasW = Math.max(1, Math.round(boardW * scale));
    const canvasH = Math.max(1, Math.round(boardH * scale));

    const canvas = document.createElement('canvas');
    canvas.width = canvasW;
    canvas.height = canvasH;
    const ctx = canvas.getContext('2d');
    if (!ctx) return { cells: 0, pasted: false };

    // Background transparent; we will draw white-filled cells with dark borders
    ctx.clearRect(0, 0, canvasW, canvasH);

    // Transform board coords to local [0, canvasW/H]
    const originLeft = boardX - boardW / 2;
    const originTop = boardY - boardH / 2;
    const pts: Array<[number, number]> = sites.map(s => [ (s.x - originLeft) * scale, (s.y - originTop) * scale ]);

    // Compute Voronoi
    const delaunay = Delaunay.from(pts);
    const vor = delaunay.voronoi([0, 0, canvasW, canvasH]);

    // Prepare coloring
    let scores: number[] | null = null;
    if (colorMode) {
      // Build spatial neighbor sets from delaunay
      const spatialNeighbors: Array<Set<number>> = new Array(pts.length).fill(0).map(() => new Set<number>());
      for (let i = 0; i < pts.length; i++) {
        const iter = (delaunay as any).neighbors ? (delaunay as any).neighbors(i) : [];
        for (const nb of iter) spatialNeighbors[i].add(nb as number);
      }

      // Collect embeddings
      const embeddings: Array<number[] | null> = sites.map(s => s.bead.getEmbedding() || null);

      // Cosine similarity matrix (only needed row-wise for top-k)
      const cosine = (a: number[] | null, b: number[] | null): number => {
        if (!a || !b || a.length !== b.length || a.length === 0) return -1; // treat missing as far
        let dot = 0, aa = 0, bb = 0;
        for (let i = 0; i < a.length; i++) { const x = a[i], y = b[i]; dot += x*y; aa += x*x; bb += y*y; }
        if (aa === 0 || bb === 0) return -1;
        return dot / (Math.sqrt(aa) * Math.sqrt(bb));
      };

      scores = new Array(pts.length).fill(0);
      if (colorMode === 'jaccard') {
        for (let i = 0; i < pts.length; i++) {
          const sims: Array<{ j: number; s: number }> = [];
          for (let j = 0; j < pts.length; j++) {
            if (i === j) continue;
            sims.push({ j, s: cosine(embeddings[i], embeddings[j]) });
          }
          sims.sort((a, b) => b.s - a.s);
          const top = sims.slice(0, k).map(x => x.j);
          const A = spatialNeighbors[i];
          const B = new Set<number>(top);
          const union = new Set<number>();
          A.forEach((v) => union.add(v));
          B.forEach((v) => union.add(v));
          let inter = 0; A.forEach((v) => { if (B.has(v)) inter++; });
          const jaccard = union.size === 0 ? 0 : (1 - inter / union.size);
          scores[i] = isFinite(jaccard) ? jaccard : 0;
        }
      } else if (colorMode === 'avgdist') {
        for (let i = 0; i < pts.length; i++) {
          const neigh = Array.from(spatialNeighbors[i]);
          if (neigh.length === 0) { scores[i] = 0; continue; }
          let sum = 0, cnt = 0;
          for (let t = 0; t < neigh.length; t++) { const j = neigh[t]; const sim = cosine(embeddings[i], embeddings[j]); if (sim !== -1) { sum += (1 - sim); cnt++; } }
          scores[i] = cnt > 0 ? (sum / cnt) : 0;
        }
      }
      // Normalize scores to [0,1]
      const min = Math.min(...scores), max = Math.max(...scores);
      const span = max - min || 1;
      scores = scores.map(v => (v - min) / span);
    }

    // Color scale: blue -> orange -> red
    const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
    const mix = (c1: [number, number, number], c2: [number, number, number], t: number): string => {
      const r = Math.round(lerp(c1[0], c2[0], t));
      const g = Math.round(lerp(c1[1], c2[1], t));
      const b = Math.round(lerp(c1[2], c2[2], t));
      return `rgb(${r}, ${g}, ${b})`;
    };
    const colormap = (t: number): string => {
      const c1: [number, number, number] = [43, 131, 186];   // #2b83ba
      const c2: [number, number, number] = [253, 174, 97];  // #fdae61
      const c3: [number, number, number] = [215, 25, 28];   // #d7191c
      if (t <= 0.5) return mix(c1, c2, t * 2);
      return mix(c2, c3, (t - 0.5) * 2);
    };

    // Draw cells
    ctx.lineWidth = outline ? 1 : 0;
    ctx.strokeStyle = outline ? '#222222' : 'rgba(0,0,0,0)';
    const prevAlpha = ctx.globalAlpha;
    ctx.globalAlpha = alpha;
    let cellCount = 0;
    for (let i = 0; i < pts.length; i++) {
      const path = vor.renderCell(i);
      if (!path) continue;
      const p = new Path2D(path);
      const fill = scores ? colormap(scores[i]) : '#ffffff';
      ctx.fillStyle = fill;
      ctx.fill(p);
      if (outline) ctx.stroke(p);
      cellCount++;
    }
    ctx.globalAlpha = prevAlpha;

    const url = canvas.toDataURL('image/png');
    const img = await window.miro.board.createImage({
      url,
      x: boardX,
      y: boardY,
      // Only set one dimension (width) to satisfy Miro API; height scales automatically
      width: boardW,
    });
    // Always send to back so stacks remain visible as a background layer
    try { await img.sendToBack(); } catch {}

    // Optional legend
    if (legend && scores) {
      const legendCanvas = document.createElement('canvas');
      const lw = 200, lh = 20; legendCanvas.width = lw; legendCanvas.height = lh;
      const lctx = legendCanvas.getContext('2d');
      if (lctx) {
        for (let x = 0; x < lw; x++) {
          const t = x / (lw - 1);
          lctx.fillStyle = colormap(t);
          lctx.fillRect(x, 0, 1, lh);
        }
        const lurl = legendCanvas.toDataURL('image/png');
        try {
          await window.miro.board.createImage({ url: lurl, x: boardX + boardW / 2 + 120, y: boardY - boardH / 2 + 20, width: 240 });
        } catch {}
      }
    }

    return { cells: cellCount, pasted: true };
  }
}


