import { Motif } from '../types/motif';

/**
 * Compute digital root for a motif code/id.
 * - Extract only digits (ignore letters and dots)
 * - Sum those digits
 * - Reduce to 1..9 via digital root; if sum is 0, stays 0
 */
export function computeCodeReduction(id: string): number {
  if (!id) return 0;
  // Extract only digits
  const digits = id.replace(/[^0-9]/g, '');
  if (!digits) return 0;
  // Sum the digits
  let sum = 0;
  for (let i = 0; i < digits.length; i++) {
    sum += parseInt(digits[i], 10) || 0;
  }
  if (sum === 0) return 0;
  // Digital root in base-10 (1..9), preserving 0
  const dr = 1 + ((sum - 1) % 9);
  return dr;
}

export interface BeadAttributes {
  codeReduction: number;
  tarotIndex?: number;
  iching?: number;
}

export function getBeadAttributes(m: Motif): BeadAttributes {
  return {
    codeReduction: computeCodeReduction(m.id),
    tarotIndex: m.tarot_index,
    iching: m.iching_hexagram_number,
  };
}


