import { MotifBead } from './MotifBead';
import { Motif } from '../types/motif';
import { computeCodeReduction } from './MotifAttributes';
import { longestCommonSubstring } from './stringSimilarity';
import { getHexagramTrigrams } from './ichingMapping';
import { getLocalizedMotifName } from './getLocalizedMotifName';
import type { Language } from './languageContext';

/**
 * Bonus detail for tracking individual multipliers
 */
export type BonusKind = 'multiplier' | 'additive';
export type BonusPhase = 'preAdd' | 'mult' | 'postAdd';

export interface BonusDetail {
  // category used for badge color/icon
  type: 'tarot' | 'iching' | 'title' | 'chapter' | 'code' | 'substring' | 'syzygy';
  // how this bonus is applied
  kind: BonusKind;
  // multiplier (for multiplier-kind)
  multiplier?: number;
  // additive points (for additive-kind)
  additivePoints?: number;
  // short label for UI (e.g., "Same tarot", "+99 code reduction")
  label: string;
  // optional evidence snippet for UI (e.g., matched words)
  evidence?: string[];
  // internal description if needed
  description?: string;
  // execution phase (for ordering of application)
  phase?: BonusPhase;
}

/**
 * Complete scoring result with breakdown
 */
export interface ScoringResult {
  totalPoints: number;
  basePoints: number;
  bonuses: BonusDetail[];
  displayText: string;
}

/**
 * Strategy interface for different scoring algorithms
 */
export interface ScoringStrategy {
  name: string;
  calculate(inputBead: MotifBead, targetBead: MotifBead, similarity: number): ScoringResult;
}

/**
 * Core scoring system that manages strategies
 */
export class ScoringSystem {
  private strategy: ScoringStrategy;
  
  constructor(strategy: ScoringStrategy) {
    this.strategy = strategy;
  }
  
  /**
   * Switch to a different scoring strategy
   */
  setStrategy(strategy: ScoringStrategy): void {
    this.strategy = strategy;
  }
  
  /**
   * Calculate score using current strategy
   */
  calculateScore(input: MotifBead, target: MotifBead, similarity: number): ScoringResult {
    return this.strategy.calculate(input, target, similarity);
  }
  
  /**
   * Format score for display
   */
  formatDisplay(result: ScoringResult): string {
    return result.displayText;
  }
  
  /**
   * Get current strategy name
   */
  getCurrentStrategyName(): string {
    return this.strategy.name;
  }
}

/**
 * Base scoring strategy implementation
 * Uses non-linear similarity scaling with bonus multipliers
 */
export class BaseStrategy implements ScoringStrategy {
  name = 'base-v2';
  
  calculate(inputBead: MotifBead, targetBead: MotifBead, similarity: number): ScoringResult {
    const basePoints = this.calculateBase(similarity);
    const bonuses = this.calculateBonuses(inputBead, targetBead, similarity);
    const totalPoints = this.applyBonuses(basePoints, bonuses);
    
    return {
      totalPoints,
      basePoints,
      bonuses,
      displayText: totalPoints.toLocaleString()
    };
  }
  
  /**
   * Calculate base points from similarity with better low-end dynamics.
   * Blend of linear, quadratic, and cubic components:
   *   120·s + 800·s² + 3000·s³
   * This yields non-zero feedback for small s, while preserving high-end expressiveness.
   */
  private calculateBase(similarity: number): number {
    const s = Math.max(0, Math.min(1, similarity || 0));
    const linear = 120 * s;       // immediate feedback at low s
    const quad = 800 * (s * s);   // mid-range lift
    const cubic = 3000 * (s * s * s); // high-end pop
    return Math.floor(linear + quad + cubic);
  }
  
  /**
   * Calculate all applicable bonuses
   */
  private calculateBonuses(inputBead: MotifBead, targetBead: MotifBead, similarity?: number): BonusDetail[] {
    const bonuses: BonusDetail[] = [];
    for (const rule of ACTIVE_RULES) {
      try {
        // I Ching rule needs similarity for hexagram pre-add calculation
        let b: BonusDetail | null;
        if (rule.id === 'iching') {
          b = this['checkIChingMatch'](inputBead, targetBead, similarity);
        } else {
          b = rule.apply(inputBead, targetBead);
        }
        if (b) bonuses.push(b);
      } catch {
        // ignore faulty rules
      }
    }
    return bonuses;
  }
  
  /**
   * Apply bonuses to base points
   */
  private applyBonuses(basePoints: number, bonuses: BonusDetail[]): number {
    let preAdd = 0;
    let postAdd = 0;
    let mult = 1.0;
    for (const b of bonuses) {
      if (b.kind === 'multiplier') {
        const m = typeof b.multiplier === 'number' ? b.multiplier : 1.0;
        mult *= m;
      } else if (b.kind === 'additive') {
        const val = b.additivePoints || 0;
        if (b.phase === 'postAdd') postAdd += val; else preAdd += val;
      }
    }
    return Math.floor((basePoints + preAdd) * mult + postAdd);
  }
  
  /**
   * Check for tarot card match
   */
  private checkTarotMatch(inputBead: MotifBead, targetBead: MotifBead): BonusDetail | null {
    const inputMotif = inputBead.getMotif();
    const targetMotif = targetBead.getMotif();
    
    if (inputMotif.tarot_index === undefined || targetMotif.tarot_index === undefined) {
      return null;
    }
    
    const a = inputMotif.tarot_index;
    const b = targetMotif.tarot_index;
    
    if (a === b) {
      return {
        type: 'tarot',
        kind: 'multiplier',
        multiplier: 1.8,
        label: 'Tarot card',
        evidence: ['both'],
        phase: 'mult'
      };
    }
    
    // Rank/Suit partials for minor arcana
    const { getTarotCard } = require('./tarotMapping');
    const ca = getTarotCard(a);
    const cb = getTarotCard(b);
    
    // If either is major arcana, don't apply partials (only exact card for majors)
    if (ca.suit === 'Major Arcana' || cb.suit === 'Major Arcana') return null;
    
    if (ca.rank === cb.rank) {
      return {
        type: 'tarot',
        kind: 'additive',
        additivePoints: 180,
        label: 'Tarot rank',
        evidence: ['rank'],
        phase: 'preAdd'
      };
    }
    if (ca.suit === cb.suit) {
      return {
        type: 'tarot',
        kind: 'additive',
        additivePoints: 180,
        label: 'Tarot suit',
        evidence: ['suit'],
        phase: 'preAdd'
      };
    }
    
    return null;
  }
  
  /**
   * Check for I Ching trigram match
   */
  private checkIChingMatch(inputBead: MotifBead, targetBead: MotifBead, similarity?: number): BonusDetail | null {
    const inputMotif = inputBead.getMotif();
    const targetMotif = targetBead.getMotif();
    
    if (inputMotif.iching_hexagram_number !== undefined && 
        targetMotif.iching_hexagram_number !== undefined) {
      
      const inputHex = inputMotif.iching_hexagram_number;
      const targetHex = targetMotif.iching_hexagram_number;
      
      // First check for exact hexagram match (pre-multiplier: +40% of base as additive)
      if (inputHex === targetHex) {
        // ×1.4 multiplier = +40% of base points, applied in preAdd phase
        // Compute base from similarity if provided, otherwise return 0 (will be recalculated later)
        let hexBonus = 0;
        if (typeof similarity === 'number') {
          const s = Math.max(0, Math.min(1, similarity));
          const base = 120 * s + 800 * (s * s) + 3000 * (s * s * s);
          hexBonus = Math.floor(base * 0.4);
        }
        return {
          type: 'iching',
          kind: 'additive',
          additivePoints: hexBonus,
          label: 'I Ching hexagram',
          description: `Same hexagram (${inputHex})`,
          evidence: ['hexagram'],
          phase: 'preAdd'
        };
      }
      
      // Otherwise check trigram symbols (not positions)
      const inputTrigrams = getHexagramTrigrams(inputHex);
      const targetTrigrams = getHexagramTrigrams(targetHex);
      if (!inputTrigrams || !targetTrigrams) return null;
      
      const inputSet = new Set([inputTrigrams.upperSymbol, inputTrigrams.lowerSymbol]);
      const targetSet = new Set([targetTrigrams.upperSymbol, targetTrigrams.lowerSymbol]);
      
      // Find which trigrams match
      const matchingTrigrams: string[] = [];
      if (inputSet.has(targetTrigrams.upperSymbol)) matchingTrigrams.push(targetTrigrams.upperSymbol);
      if (inputSet.has(targetTrigrams.lowerSymbol)) matchingTrigrams.push(targetTrigrams.lowerSymbol);
      // Deduplicate
      const uniqueMatches = Array.from(new Set(matchingTrigrams));
      
      if (uniqueMatches.length === 2) {
        // Both trigrams match (swapped order)
        return {
          type: 'iching',
          kind: 'additive',
          additivePoints: 128,
          label: 'I Ching trigrams',
          description: `Both trigrams match (swapped)`,
          evidence: [`pair:${uniqueMatches[0]},${uniqueMatches[1]}`],
          phase: 'postAdd'
        };
      }
      if (uniqueMatches.length === 1) {
        // One trigram matches
        return {
          type: 'iching',
          kind: 'additive',
          additivePoints: 64,
          label: 'I Ching trigram',
          description: `One trigram matches`,
          evidence: [`trigram:${uniqueMatches[0]}`],
          phase: 'postAdd'
        };
      }
    }
    
    return null;
  }
  
  /**
   * Get current language from localStorage or default to 'en'
   */
  private getCurrentLanguage(): Language {
    const stored = localStorage.getItem('gbg-language-preference');
    return (stored === 'en' || stored === 'pt_br') ? stored as Language : 'en';
  }

  /**
   * Check for title word matches
   */
  private checkTitleMatch(inputBead: MotifBead, targetBead: MotifBead): BonusDetail | null {
    const input = inputBead.getMotif();
    const target = targetBead.getMotif();
    const language = this.getCurrentLanguage();
    const inputName = getLocalizedMotifName(input, language);
    const targetName = getLocalizedMotifName(target, language);
    // Simple word matching - filter by length > 3 and ignore common words
    const ignore = language === 'pt_br' 
      ? new Set(['o', 'a', 'os', 'as', 'de', 'do', 'da', 'dos', 'das', 'em', 'no', 'na', 'nos', 'nas', 'por', 'para', 'com', 'sem', 'que', 'como', 'onde'])
      : new Set(['the', 'and', 'with', 'from', 'into', 'over', 'under', 'this', 'that', 'these', 'those']);
    const inputWords = inputName.toLowerCase().split(/\s+/).filter(w => w.length > 3 && !ignore.has(w));
    const targetWords = targetName.toLowerCase().split(/\s+/).filter(w => w.length > 3 && !ignore.has(w));
    const matched: string[] = [];
    const inputSet = new Set(inputWords);
    for (const w of targetWords) if (inputSet.has(w)) matched.push(w);
    const matches = matched.length;
    if (matches > 0) {
      const multiplier = 1.0 + (Math.min(matches, 2) * 0.25);
      return {
        type: 'title',
        kind: 'multiplier',
        multiplier,
        label: 'Title words',
        evidence: matched.slice(0, 3),
        description: `${matches} title word match(es)`,
        phase: 'mult'
      };
    }
    return null;
  }
  
  /**
   * Check for chapter match
   */
  private checkChapterMatch(inputBead: MotifBead, targetBead: MotifBead): BonusDetail | null {
    const inputChapter = inputBead.getMotif().chapter;
    const targetChapter = targetBead.getMotif().chapter;
    
    if (inputChapter && targetChapter && inputChapter === targetChapter) {
      return {
        type: 'chapter',
        kind: 'multiplier',
        multiplier: 1.2,
        label: 'Chapter match',
        description: `Same chapter (${inputChapter})`,
        phase: 'mult'
      };
    }
    
    return null;
  }
}

/**
 * Default scoring system instance
 */
export const defaultScoringSystem = new ScoringSystem(new BaseStrategy());

// --- Rule system ---

export interface BonusRule {
  id: string;
  label: string;
  kind: BonusKind;
  phase: BonusPhase;
  apply(input: MotifBead, target: MotifBead): BonusDetail | null;
}

const tarotRule: BonusRule = {
  id: 'tarot',
  label: 'Tarot match',
  kind: 'multiplier',
  phase: 'mult',
  apply: (input, target) => new BaseStrategy()['checkTarotMatch'](input, target)
};

const ichingRule: BonusRule = {
  id: 'iching',
  label: 'I Ching trigram',
  kind: 'multiplier',
  phase: 'mult',
  apply: (input, target) => new BaseStrategy()['checkIChingMatch'](input, target)
};

const titleWordsRule: BonusRule = {
  id: 'title',
  label: 'Title words',
  kind: 'multiplier',
  phase: 'mult',
  apply: (input, target) => new BaseStrategy()['checkTitleMatch'](input, target)
};

const chapterRule: BonusRule = {
  id: 'chapter',
  label: 'Chapter match',
  kind: 'multiplier',
  phase: 'mult',
  apply: (input, target) => new BaseStrategy()['checkChapterMatch'](input, target)
};

const codeReductionRule: BonusRule = {
  id: 'code',
  label: 'Digital Reduction',
  kind: 'additive',
  phase: 'preAdd',
  apply: (input, target) => {
    const a = computeCodeReduction(input.getMotif().id);
    const b = computeCodeReduction(target.getMotif().id);
    if (a === b) {
      return {
        type: 'code',
        kind: 'additive',
        additivePoints: 99,
        label: 'Digital Reduction match',
        description: `Same reduction (${a})`,
        phase: 'preAdd'
      };
    }
    return null;
  }
};

const substringRule: BonusRule = {
  id: 'substring',
  label: 'Common substring',
  kind: 'additive',
  phase: 'postAdd',
  apply: (input, target) => {
    // Get current language from localStorage
    const stored = localStorage.getItem('gbg-language-preference');
    const language: Language = (stored === 'en' || stored === 'pt_br') ? stored as Language : 'en';
    const a = `${input.getMotif().id} ${getLocalizedMotifName(input.getMotif(), language)}`;
    const b = `${target.getMotif().id} ${getLocalizedMotifName(target.getMotif(), language)}`;
    const res = longestCommonSubstring(a, b, 4);
    if (!res) return null;
    const L = res.length;
    // Quadratic growth: L^2 * 10 (balanced, doesn't explode)
    const points = Math.max(0, Math.round(L * L * 10));
    if (points <= 0) return null;
    return {
      type: 'substring',
      kind: 'additive',
      additivePoints: points,
      label: 'Common substring',
      evidence: [res.substring],
      description: `L=${L}, +${points}`,
      phase: 'postAdd'
    } as BonusDetail;
  }
};

const syzygyRule: BonusRule = {
  id: 'syzygy',
  label: 'Syzygy',
  kind: 'additive',
  phase: 'preAdd',
  apply: (input, target) => {
    const drA = computeCodeReduction(input.getMotif().id);
    const drB = computeCodeReduction(target.getMotif().id);
    // Syzygy: DR sum == 9 and both > 0
    if (drA > 0 && drB > 0 && drA + drB === 9) {
      // Sort so larger number comes first (CCRU notation)
      const [larger, smaller] = drA >= drB ? [drA, drB] : [drB, drA];
      return {
        type: 'syzygy',
        kind: 'additive',
        additivePoints: 360,
        label: 'Syzygy',
        evidence: ['pair', `${smaller}::${larger}`],
        description: `DR sum = 9 (${drA} + ${drB})`,
        phase: 'preAdd'
      } as BonusDetail;
    }
    return null;
  }
};

export const ACTIVE_RULES: BonusRule[] = [
  tarotRule,
  ichingRule,
  chapterRule,
  codeReductionRule,
  substringRule,
  syzygyRule
];

/**
 * Convenience helper: calculate score directly from Motif objects (used by Practice mode)
 */
export function calculateScoreByMotifs(inputMotif: Motif, targetMotif: Motif, similarity: number): ScoringResult {
  const beadLike = (m: Motif) => ({ getMotif: () => m }) as unknown as MotifBead;
  const strat = new BaseStrategy();
  const basePoints = strat['calculateBase'](similarity as number);
  const bonuses = strat['calculateBonuses'](beadLike(inputMotif), beadLike(targetMotif), similarity);
  const totalPoints = strat['applyBonuses'](basePoints, bonuses);
  return {
    totalPoints,
    basePoints,
    bonuses,
    displayText: totalPoints.toLocaleString()
  };
}
