type Hand = {
  cards: RawMotif[]; // 5 cards
  target: RawMotif;  // 1 target
};

type GameMode = 'practice' | 'survival';

type SurvivalResult = {
  mode: 'survival';
  roundsSurvived: number;
  totalScore: number;      // Total points accumulated
  finalLife: number;       // Life when died
  averageScore: number;
  maxSingleScore: number;
  playedAt: string;        // ISO timestamp
};

// Balance parameters - easily accessible for tuning
export const SURVIVAL_CONFIG = {
  // Damage settings
  initialDamage: 50,
  damageIncrease: 10,
  damageMultiplier: 1.0,  // For difficulty scaling
  
  // Life settings
  initialLife: 0,         // Starting life
  lifeRegen: 0,           // Per-round regen (future)
  
  // Scoring adjustments (if needed)
  scoreMultiplier: 1.0,
  
  // Round progression
  maxRounds: Infinity,     // Optional cap
};

function sampleDistinct<T>(arr: T[], k: number): T[] {
  const n = arr.length;
  const res: T[] = [];
  const used = new Set<number>();
  while (res.length < Math.min(k, n)) {
    const idx = Math.floor(Math.random() * n);
    if (used.has(idx)) continue;
    used.add(idx);
    res.push(arr[idx]);
  }
  return res;
}

/**
 * Draws a hand ensuring the sum of similarities between cards and target meets a threshold.
 * This prevents frustrating hands where all cards are poorly related to the target.
 * @param pool - Available motifs to draw from
 * @param minSimilaritySum - Minimum sum of similarities (default: 0.1)
 * @param maxRetries - Maximum attempts before giving up (default: 100)
 * @returns Hand object if threshold met, or null if max retries exceeded
 */
function drawHandWithThreshold(
  pool: RawMotif[],
  minSimilaritySum: number = 0.1,
  maxRetries: number = 100
): Hand | null {
  if (pool.length < 6) return null;

  for (let attempt = 0; attempt < maxRetries; attempt++) {
    // Sample 6 distinct motifs (5 cards + 1 target)
    const six = sampleDistinct(pool, 6);
    const cards = six.slice(0, 5);
    const target = six[5];

    // Calculate similarity for each card against the target
    const similarities = cards.map(card =>
      cosineSimilarity(card.embedding || [], target.embedding || [])
    );

    // Sum all similarities
    const similaritySum = similarities.reduce((sum, sim) => sum + sim, 0);

    // If threshold is met, return this hand
    if (similaritySum >= minSimilaritySum) {
      return { cards, target };
    }
  }

  // If max retries exceeded, return null (caller can handle fallback)
  return null;
}

function useMotifs(): RawMotif[] {
  const { language } = useLanguage();
  // Use full bundled motifs dataset (all 1265 motifs)
  return useMemo(() => {
    const all = (motifsData as unknown as Motif[]) || [];
    // Keep only fields needed for practice mode, with localized names
    const mapped: RawMotif[] = all.map(m => ({
      id: m.id,
      name: getLocalizedMotifName(m, language),
      embedding: m.embedding || [],
      image_path: m.image_path,
      tarot_index: m.tarot_index,
      iching_hexagram_number: m.iching_hexagram_number,
      chapter: m.chapter,
    }));
    return mapped;
  }, [language]);
}

// Helper to get full Motif object by ID for localized name lookup
function getMotifById(id: string): Motif | undefined {
  const all = (motifsData as unknown as Motif[]) || [];
  return all.find(m => m.id === id);
}

export default function Practice(): React.ReactElement {
  const { language } = useLanguage();
  const motifs = useMotifs();
  const [gameMode, setGameMode] = useState<GameMode>('practice');
  const [hand, setHand] = useState<Hand | null>(null);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [scoreTotal, setScoreTotal] = useState<number>(0);
  const [roundsPlayed, setRoundsPlayed] = useState<number>(0);
  const [playing, setPlaying] = useState<boolean>(false);
  const [helpOpen, setHelpOpen] = useState<boolean>(false);
  const [highScoresOpen, setHighScoresOpen] = useState<boolean>(false);
  const [shareOpen, setShareOpen] = useState<boolean>(false);
  const publicBase = process.env.PUBLIC_URL || '';
  // Prefer a bundled asset if present under src/assets; otherwise fall back to public path.
  // This avoids dev-server public path quirks while keeping zero overhead if the asset isn't bundled.
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const qrBundled: any = (() => {
    try {
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      const m = require('../assets/qrcode.jpeg');
      return m && (m.default || m);
    } catch (_e) {
      return null;
    }
  })();
  const qrUrlResolved: string = qrBundled || `${publicBase}/images/qrcode.jpeg?v=1`;
  // Direct link to QR code in public/images
  const [showNameEntry, setShowNameEntry] = useState<boolean>(false);
  const [submittingScore, setSubmittingScore] = useState<boolean>(false);
  const [scoreSubmitted, setScoreSubmitted] = useState<boolean>(false);
  
  // Survival mode state
  const [life, setLife] = useState<number>(SURVIVAL_CONFIG.initialLife);
  const [currentRound, setCurrentRound] = useState<number>(0);
  const [isDead, setIsDead] = useState<boolean>(false);
  const [survivalResult, setSurvivalResult] = useState<SurvivalResult | null>(null);
  const [fusionCommitted, setFusionCommitted] = useState<boolean>(false);
  const [maxSingleScore, setMaxSingleScore] = useState<number>(0);
  
  // Hexagram JSON view toggle state
  const [showTargetJSON, setShowTargetJSON] = useState<boolean>(false);
  const [showFusionJSON, setShowFusionJSON] = useState<boolean>(false);

  useEffect(() => {
    if (motifs.length > 10) {
      newRound();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [motifs.length]);

  // Update hand when language changes to refresh localized names
  useEffect(() => {
    if (hand) {
      // Recreate hand with updated motifs (which have new localized names)
      const updatedCards = hand.cards.map(card => {
        const updated = motifs.find(m => m.id === card.id);
        return updated || card;
      });
      const updatedTarget = motifs.find(m => m.id === hand.target.id) || hand.target;
      setHand({ cards: updatedCards, target: updatedTarget });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [language, motifs]); // Intentionally exclude 'hand' to avoid infinite loop

  function newRound(): void {
    // Try to draw a hand that meets the similarity threshold
    const hand = drawHandWithThreshold(motifs, 0.1, 100);
    
    // Fallback to any hand if threshold can't be met (should be rare with 1265 motifs)
    if (!hand) {
      const six = sampleDistinct(motifs, 6);
      const cards = six.slice(0, 5);
      const target = six[5];
      setHand({ cards, target });
    } else {
      setHand(hand);
    }
    
    setSelectedIds(new Set());
    setFusionCommitted(false);
  }

  function toggleMode(): void {
    const newMode: GameMode = gameMode === 'practice' ? 'survival' : 'practice';
    setGameMode(newMode);
    
    if (newMode === 'survival') {
      // Reset survival state when entering survival mode
      setLife(SURVIVAL_CONFIG.initialLife);
      setCurrentRound(0);
      setIsDead(false);
      setSurvivalResult(null);
      setMaxSingleScore(0);
      setScoreTotal(0);
      setRoundsPlayed(0);
      newRound();
    }
    // When switching to practice, preserve survival state (don't reset)
  }

  function calculateDamage(round: number): number {
    // Fibonacci(round) * 99; round starts at 1
    const fib = (n: number): number => {
      if (n <= 1) return 1;
      let a = 1, b = 1;
      for (let i = 3; i <= n; i++) {
        const c = a + b;
        a = b;
        b = c;
      }
      return b;
    };
    const dmg = fib(Math.max(1, Math.floor(round))) * 99;
    return Math.floor(dmg * SURVIVAL_CONFIG.damageMultiplier);
  }

  // Calculate next round's damage (for display and application)
  const nextDamage = useMemo(() => {
    if (gameMode === 'survival') {
      return calculateDamage(currentRound + 1);
    }
    return 0;
  }, [gameMode, currentRound]);

  function toggleCard(id: string): void {
    // In survival mode, prevent card changes if fusion is committed
    if (gameMode === 'survival' && fusionCommitted) {
      return;
    }
    setSelectedIds(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  }

  // Always calculate fusion (even in survival mode before commit) for score hints
  const fusion = useMemo(() => {
    if (!hand) return null;
    const selected = hand.cards.filter(c => selectedIds.has(c.id));
    if (selected.length === 0) return null;
    
    // If only one card is selected, use it directly (no fusion)
    if (selected.length === 1) {
      const only = selected[0];
      const simToTarget = cosineSimilarity(only.embedding || [], hand.target.embedding || []);
      const scoring = calculateScoreByMotifs(only as unknown as Motif, hand.target as unknown as Motif, simToTarget);
      return { result: only, similarity: simToTarget, scoring };
    }
    // For multiple, fuse then find nearest (excluding inputs)
    const avg = averageEmbeddings(selected.map(c => c.embedding || []));
    if (!avg) return null;
    const pool = motifs;
    const exclude = new Set<string>(selected.map(c => c.id));
    const { motif } = findNearest(avg, pool, exclude);
    if (!motif) return null;
    const simToTarget = cosineSimilarity(motif.embedding || [], hand.target.embedding || []);
    const scoring = calculateScoreByMotifs(motif as Motif, hand.target as Motif, simToTarget);
    return { result: motif, similarity: simToTarget, scoring };
  }, [hand, selectedIds, motifs, language]);

  function commitFusion(): void {
    if (gameMode === 'survival' && selectedIds.size >= 1) {
      setFusionCommitted(true);
    }
  }

  function onNextHand(): void {
    setRoundsPlayed(r => r + 1);
    if (fusion?.scoring.totalPoints) setScoreTotal(s => s + fusion.scoring.totalPoints);
    newRound();
  }

  function onShuffle(): void {
    if (!hand) return;
    const cards = sampleDistinct(motifs.filter(m => m.id !== hand.target.id), 5);
    setHand({ cards, target: hand.target });
    setSelectedIds(new Set());
  }

  function onReset(): void {
    setScoreTotal(0);
    setRoundsPlayed(0);
    if (gameMode === 'survival') {
      setLife(SURVIVAL_CONFIG.initialLife);
      setCurrentRound(0);
      setIsDead(false);
      setSurvivalResult(null);
      setMaxSingleScore(0);
      setFusionCommitted(false);
    }
    newRound();
  }

  function handlePlay(): void {
    if (!fusion) return;
    
    const score = fusion.scoring.totalPoints;
    
    if (gameMode === 'practice') {
      // Practice mode: normal flow
      setPlaying(true);
      setTimeout(() => {
        setPlaying(false);
        setRoundsPlayed(r => r + 1);
        setScoreTotal(s => s + score);
        newRound();
      }, 200);
    } else {
      // Survival mode: add to life, apply damage, check death
      setPlaying(true);
      setTimeout(() => {
        setPlaying(false);
        
        // Update max single score
        if (score > maxSingleScore) {
          setMaxSingleScore(score);
        }
        
        // Add score to life
        const newLife = life + score;
        setLife(newLife);
        setScoreTotal(s => s + score);
        setRoundsPlayed(r => r + 1);
        
        // Calculate damage for next round (the round we just completed + 1)
        const nextRound = currentRound + 1;
        const damage = syzygyActive ? 0 : calculateDamage(nextRound);
        
        // Apply damage
        const lifeAfterDamage = newLife - damage;
        
        // Update round counter
        setCurrentRound(nextRound);
        setLife(lifeAfterDamage);
        
        // Check if dead
        if (lifeAfterDamage < 0) {
          setIsDead(true);
          const result: SurvivalResult = {
            mode: 'survival',
            roundsSurvived: nextRound,
            totalScore: scoreTotal + score,
            finalLife: lifeAfterDamage,
            averageScore: (scoreTotal + score) / (roundsPlayed + 1),
            maxSingleScore: Math.max(maxSingleScore, score),
            playedAt: new Date().toISOString(),
          };
          setSurvivalResult(result);
        } else {
          // Alive: continue to next round
          newRound();
        }
      }, 200);
    }
  }

  function handlePlayAgain(): void {
    setIsDead(false);
    setSurvivalResult(null);
    setShowNameEntry(false);
    setScoreSubmitted(false);
    setLife(SURVIVAL_CONFIG.initialLife);
    setCurrentRound(0);
    setScoreTotal(0);
    setRoundsPlayed(0);
    setMaxSingleScore(0);
    setFusionCommitted(false);
    newRound();
  }

  async function handleSubmitHighScore(name: string): Promise<void> {
    if (!survivalResult || scoreSubmitted) return;
    
    setSubmittingScore(true);
    try {
      const result = await submitHighScore({
        name: name || 'Anonymous',
        roundsSurvived: survivalResult.roundsSurvived,
        totalScore: survivalResult.totalScore,
        averageScore: survivalResult.averageScore,
        maxSingleScore: survivalResult.maxSingleScore,
        playedAt: survivalResult.playedAt,
      });
      
      if (result.success) {
        setScoreSubmitted(true);
        setShowNameEntry(false);
        // Optionally show a success message
      } else {
        console.error('Failed to submit high score:', result.error);
        // Still close dialog, but could show error message
        setShowNameEntry(false);
      }
    } catch (error) {
      console.error('Error submitting high score:', error);
      setShowNameEntry(false);
    } finally {
      setSubmittingScore(false);
    }
  }

  function onSubmitScore(): void {
    try {
      const entry = {
        at: new Date().toISOString(),
        total: scoreTotal,
        rounds: roundsPlayed,
      };
      const key = 'practice-highscores';
      const existing = JSON.parse(localStorage.getItem(key) || '[]');
      existing.push(entry);
      localStorage.setItem(key, JSON.stringify(existing));
      // Stub: wire this to Sheets later (silent save)
    } catch {
      // ignore
    }
  }

  function imageSrc(m: RawMotif): string | undefined {
    return resolvePublicImagePath(m.image_path) || undefined;
  }

  const activeBonusTypes = new Set((fusion?.scoring.bonuses || []).map(b => b.type));
  const uniqueIChing = useMemo(() => {
    const s = new Set<number>();
    for (const m of motifs) if (typeof m.iching_hexagram_number === 'number') s.add(m.iching_hexagram_number);
    return s;
  }, [motifs]);

  const averageScore = useMemo(() => {
    return roundsPlayed > 0 ? scoreTotal / roundsPlayed : 0;
  }, [scoreTotal, roundsPlayed]);

  function renderWithHighlight(text: string | undefined, match: string | undefined): React.ReactNode {
    const t = text || '';
    const m = (match || '').trim();
    if (!t || !m) return t;
    const idx = t.toLowerCase().indexOf(m.toLowerCase());
    if (idx === -1) return t;
    const before = t.slice(0, idx);
    const mid = t.slice(idx, idx + m.length);
    const after = t.slice(idx + m.length);
    return (
      <>
        {before}
        <span style={{ color: '#4fc1ff', borderBottom: '1px dashed #4fc1ff' }}>{mid}</span>
        {after}
      </>
    );
  }

  // Extract evidence from bonuses
  const ichingEvidence = useMemo(() => {
    const b = fusion?.scoring.bonuses || [];
    const ich = b.find((x: any) => x.type === 'iching' && Array.isArray(x.evidence));
    return ich?.evidence || [];
  }, [fusion?.scoring.bonuses]);

  const tarotEvidence = useMemo(() => {
    const b = fusion?.scoring.bonuses || [];
    const tar = b.find((x: any) => x.type === 'tarot' && Array.isArray(x.evidence));
    return tar?.evidence || [];
  }, [fusion?.scoring.bonuses]);

  const syzygyActive = useMemo(() => {
    const b = fusion?.scoring.bonuses || [];
    return b.some((x: any) => x.type === 'syzygy');
  }, [fusion?.scoring.bonuses]);

  // Extract common substring (if any) from bonuses evidence
  const commonSubstr: string | undefined = useMemo(() => {
    const b = fusion?.scoring.bonuses || [];
    const s = b.find((x: any) => x.label === 'Common substring' && Array.isArray(x.evidence) && x.evidence.length > 0);
    return s?.evidence?.[0];
  }, [fusion?.scoring.bonuses]);

  // JSON Display Component for Hexagram Data
  function HexagramJSONDisplay({ hexNumber }: { hexNumber: number }) {
    const hexData = getHexagramData(hexNumber);
    if (!hexData) return null;
    
    return (
      <div
        style={{
          background: '#1e1e1e',
          border: '1px solid #3a3a3a',
          borderRadius: 4,
          padding: '8px',
          fontSize: 11,
          fontFamily: 'monospace',
          whiteSpace: 'pre',
          lineHeight: 1.4,
        }}
      >
        <div style={{ color: '#ce9178' }}>{'{'}</div>
        <div style={{ paddingLeft: 12 }}>
          <div>
            <span style={{ color: '#9cdcfe' }}>"number"</span>
            <span style={{ color: '#d4d4d4' }}>: </span>
            <span style={{ color: '#b5cea8' }}>{hexData.number}</span>
            <span style={{ color: '#d4d4d4' }}>,</span>
          </div>
          <div>
            <span style={{ color: '#9cdcfe' }}>"chinese"</span>
            <span style={{ color: '#d4d4d4' }}>: </span>
            <span style={{ color: '#ce9178' }}>"</span>
            <span style={{ color: '#4ec9b0' }}>{hexData.chinese}</span>
            <span style={{ color: '#ce9178' }}>"</span>
            <span style={{ color: '#d4d4d4' }}>,</span>
          </div>
          <div>
            <span style={{ color: '#9cdcfe' }}>"pinyin"</span>
            <span style={{ color: '#d4d4d4' }}>: </span>
            <span style={{ color: '#ce9178' }}>"</span>
            <span style={{ color: '#4ec9b0' }}>{hexData.pinyin}</span>
            <span style={{ color: '#ce9178' }}>"</span>
            <span style={{ color: '#d4d4d4' }}>,</span>
          </div>
          <div>
            <span style={{ color: '#9cdcfe' }}>"unicode"</span>
            <span style={{ color: '#d4d4d4' }}>: </span>
            <span style={{ color: '#ce9178' }}>"</span>
            <span style={{ color: '#4ec9b0' }}>{hexData.unicode}</span>
            <span style={{ color: '#ce9178' }}>"</span>
            <span style={{ color: '#d4d4d4' }}>,</span>
          </div>
          <div>
            <span style={{ color: '#9cdcfe' }}>"unicode_hex"</span>
            <span style={{ color: '#d4d4d4' }}>: </span>
            <span style={{ color: '#ce9178' }}>"</span>
            <span style={{ color: '#4ec9b0' }}>{hexData.unicode_hex}</span>
            <span style={{ color: '#ce9178' }}>"</span>
            <span style={{ color: '#d4d4d4' }}>,</span>
          </div>
          <div>
            <span style={{ color: '#9cdcfe' }}>"english"</span>
            <span style={{ color: '#d4d4d4' }}>: </span>
            <span style={{ color: '#ce9178' }}>"</span>
            <span style={{ color: '#dcdcaa' }}>{hexData.english}</span>
            <span style={{ color: '#ce9178' }}>"</span>
          </div>
        </div>
        <div style={{ color: '#ce9178' }}>{'}'}</div>
      </div>
    );
  }

  // Render I Ching hexagram with evidence-based highlighting
  function renderIChing(hexNumber: number | undefined): React.ReactNode {
    if (hexNumber === undefined) return null;
    const split = splitHexagramSymbol(hexNumber);
    if (!split) return getIChingCompact(hexNumber);
    
    const hasHexagram = ichingEvidence.includes('hexagram');
    const hasPair = ichingEvidence.find((e: string) => e.startsWith('pair:'));
    const hasTrigram = ichingEvidence.find((e: string) => e.startsWith('trigram:'));
    
    // Extract trigram symbols from evidence
    const trigramSymbol = hasTrigram ? (hasTrigram as string).replace('trigram:', '') : null;
    const pairSymbols = hasPair ? (hasPair as string).replace('pair:', '').split(',') : [];
    
    const upperColor = hasHexagram ? '#ffd76a' : 
                      (trigramSymbol === split.upper || pairSymbols.includes(split.upper)) ? '#d23b3b' : undefined;
    const lowerColor = hasHexagram ? '#ffd76a' :
                      (trigramSymbol === split.lower || pairSymbols.includes(split.lower)) ? '#d23b3b' : undefined;
    
    const upperSymbol = <span style={{ color: upperColor }}>{split.upper}</span>;
    const lowerSymbol = <span style={{ color: lowerColor }}>{split.lower}</span>;
    
    return (
      <>
        {upperSymbol}
        {lowerSymbol}
      </>
    );
  }

  // Render Tarot with evidence-based highlighting (for Target/Fusion Result)
  function renderTarot(tarotIndex: number | undefined, useEvidence: boolean = true): React.ReactNode {
    if (tarotIndex === undefined) return null;
    const card = getTarotCard(tarotIndex);
    
    if (!useEvidence) {
      // For hand cards, just render normally
      return <span>{getTarotCompact(tarotIndex)}</span>;
    }
    
    const hasBoth = tarotEvidence.includes('both');
    const hasRank = tarotEvidence.includes('rank');
    const hasSuit = tarotEvidence.includes('suit');
    
    if (card.suit === 'Major Arcana') {
      return <span style={{ color: hasBoth ? '#ffd76a' : undefined }}>{getTarotCompact(tarotIndex)}</span>;
    }
    
    const rankColor = hasBoth ? '#ffd76a' : (hasRank ? '#d23b3b' : undefined);
    const suitColor = hasBoth ? '#ffd76a' : (hasSuit ? '#d23b3b' : undefined);
    
    return (
      <>
        <span style={{ color: rankColor }}>{card.rank}</span>
        <span style={{ color: suitColor }}>{card.suitEmoji}</span>
      </>
    );
  }

  // Render I Ching for hand cards (no evidence)
  function renderIChingSimple(hexNumber: number | undefined): React.ReactNode {
    if (hexNumber === undefined) return null;
    return <span>{getIChingCompact(hexNumber)}</span>;
  }

  return (
    <div className={`practice-container ${gameMode === 'survival' ? 'survival-mode' : ''}`} style={{ padding: '8px 12px', maxWidth: 480, margin: '0 auto', background: 'var(--bg)', color: 'var(--text)', minHeight: '100vh' }}>
      {/* Header Row 1: title left; controls (Help, Share, HS) right - no wrap */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8, marginTop: 4, flexWrap: 'wrap' }}>
        <h2 style={{ margin: '4px 0', textAlign: 'left', display: 'flex', alignItems: 'center', gap: 8, fontSize: 20, lineHeight: 1.05 }}>
          <span>Glass Bead Game</span>
        </h2>

        <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'nowrap', justifyContent: 'flex-end', flex: 1 }}>
          {/* Help (bigger ?; no motif counter) */}
          <button aria-label="Help" onClick={() => setHelpOpen(true)} style={{ height: 28, padding: '0 12px', borderRadius: 14, border: '1px solid var(--border)', background: 'rgba(0,0,0,0.3)', color: 'var(--text)', display: 'flex', alignItems: 'center', gap: 6, fontSize: 12, cursor: 'pointer', whiteSpace: 'nowrap' }}>
            <span style={{ fontWeight: 800, fontSize: 16 }}>?</span>
          </button>
          {/* Share */}
          <button aria-label="Share" onClick={() => setShareOpen(true)} style={{ height: 28, padding: '0 10px', borderRadius: 14, border: '1px solid var(--border)', background: 'var(--panel)', color: 'var(--text)', fontSize: 12, cursor: 'pointer', whiteSpace: 'nowrap' }}>
            Share
          </button>
          {/* HS (Highscores) */}
          <button aria-label="Highscores" onClick={() => setHighScoresOpen(true)} style={{ height: 28, padding: '0 10px', borderRadius: 14, border: '1px solid var(--border)', background: 'var(--panel)', color: 'var(--text)', fontSize: 12, cursor: 'pointer', whiteSpace: 'nowrap' }}>
            HS
          </button>
        </div>
      </div>

      {/* Header Row 2: pills + mode toggle (can wrap) */}
      <div style={{ display: 'flex', justifyContent: 'flex-start', gap: 8, marginTop: 4, marginBottom: 6, flexWrap: 'wrap' }}>
        {gameMode === 'survival' ? (
          <>
            <div className="mono" style={{ padding: '6px 10px', background: 'rgba(201,120,95,0.2)', color: 'var(--survival-accent)', borderRadius: 9999, fontWeight: 700, fontSize: 12 }}>Life: {life.toLocaleString()}</div>
            <div className="mono" style={{ padding: '6px 10px', background: 'rgba(244,135,113,0.16)', color: syzygyActive ? '#00ff66' : 'var(--error)', textDecoration: syzygyActive ? 'line-through' : 'none', borderRadius: 9999, fontWeight: 700, fontSize: 12 }}>Next: -{nextDamage}</div>
            <div className="mono" style={{ padding: '6px 10px', background: 'rgba(79,193,255,0.16)', color: 'var(--accent-cyan)', borderRadius: 9999, fontWeight: 700, fontSize: 12 }}>Round: {currentRound}</div>
          </>
        ) : (
          <>
            <div className="mono" style={{ padding: '6px 10px', background: 'rgba(86,156,214,0.16)', color: 'var(--accent-blue)', borderRadius: 9999, fontWeight: 700, fontSize: 12 }}>Total: {scoreTotal.toLocaleString()}</div>
            <div className="mono" style={{ padding: '6px 10px', background: 'rgba(79,193,255,0.16)', color: 'var(--accent-cyan)', borderRadius: 9999, fontWeight: 700, fontSize: 12 }}>Hands: {roundsPlayed}</div>
            <div className="mono" style={{ padding: '6px 10px', background: 'rgba(137,209,133,0.16)', color: 'var(--success)', borderRadius: 9999, fontWeight: 700, fontSize: 12 }}>Avg: {averageScore.toFixed(1)}</div>
          </>
        )}
        <LanguageSwitcher />
        <button
          onClick={toggleMode}
          className="mono"
          style={{
            padding: '6px 10px',
            background: gameMode === 'survival' ? 'rgba(201,120,95,0.2)' : 'rgba(244,135,113,0.16)',
            color: gameMode === 'survival' ? 'var(--survival-accent)' : '#d97757',
            border: `1px solid ${gameMode === 'survival' ? 'rgba(201,120,95,0.4)' : 'rgba(244,135,113,0.3)'}`,
            borderRadius: 9999,
            fontWeight: 700,
            fontSize: 12,
            cursor: 'pointer'
          }}
        >
          {gameMode === 'survival' ? 'Practice' : 'Survival'}
        </button>
      </div>

      {/* Target */}
      <div style={{ border: '1px solid var(--border)', borderRadius: 8, padding: 8, marginBottom: 8, background: 'var(--panel)', position: 'relative' }}>
        <div style={{ fontWeight: 600, marginBottom: 8, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <span>Target</span>
          {hand?.target.iching_hexagram_number !== undefined && (
            <button
              onClick={() => setShowTargetJSON(!showTargetJSON)}
              style={{
                background: showTargetJSON ? 'rgba(184,146,255,0.2)' : 'transparent',
                border: '1px solid var(--border)',
                borderRadius: 4,
                padding: '4px 8px',
                fontSize: 16,
                cursor: 'pointer',
                color: 'var(--text)',
                fontFamily: 'monospace'
              }}
              title="Toggle hexagram JSON view"
            >
              {getIChingCompact(hand.target.iching_hexagram_number)}
            </button>
          )}
        </div>
        <div style={{ display: 'flex', gap: 8, alignItems: 'flex-start' }}>
          {hand && imageSrc(hand.target) ? (
            <img src={imageSrc(hand.target)!} alt={getLocalizedMotifName(hand.target as unknown as Motif, language)} style={{ width: 120, height: 120, flexShrink: 0, objectFit: 'cover', borderRadius: 4, border: '1px solid #3a3a3a' }} />
          ) : (
            <div style={{ width: 120, height: 120, flexShrink: 0, background: '#f2f2f2', borderRadius: 4 }} />
          )}
          <div style={{ fontSize: 13, flex: 1 }}>
            {showTargetJSON && hand?.target.iching_hexagram_number !== undefined ? (
              <HexagramJSONDisplay hexNumber={hand.target.iching_hexagram_number} />
            ) : (
              <>
                <div className="mono" style={{ fontWeight: 700, display: 'flex', alignItems: 'center', gap: 6, color: syzygyActive ? '#00ff66' : '#b892ff' }}>
                  <span>{renderWithHighlight(hand?.target.id, commonSubstr)}</span>
                  {hand?.target?.id && (
                    <span style={{ fontSize: 11, opacity: 0.9, color: syzygyActive ? '#00ff66' : undefined }}>DR:{computeCodeReduction(hand.target.id)}</span>
                  )}
                </div>
                <div style={{ marginTop: 4, color: 'var(--muted)', fontSize: 18 }}>
                  {hand?.target.tarot_index !== undefined && renderTarot(hand.target.tarot_index)}
                  {hand?.target.iching_hexagram_number !== undefined && '  '}
                  {hand?.target.iching_hexagram_number !== undefined && renderIChing(hand.target.iching_hexagram_number)}
                </div>
                <div style={{ marginTop: 4 }}>{renderWithHighlight(hand?.target ? getLocalizedMotifName(hand.target as unknown as Motif, language) : '', commonSubstr)}</div>
              </>
            )}
          </div>
        </div>
      </div>

      {/* Fusion Result */}
      <div data-iching-container style={{ border: '1px solid var(--border)', borderRadius: 8, padding: 8, marginBottom: 8, transition: 'transform 200ms ease', transform: playing ? 'scale(1.03)' : 'scale(1)', background: 'var(--panel)', position: 'relative' }}>
        <div style={{ fontWeight: 600, marginBottom: 8, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <span>Fusion Result</span>
          {fusion && (fusion.result as any).iching_hexagram_number !== undefined && (
            <button
              onClick={() => setShowFusionJSON(!showFusionJSON)}
              style={{
                background: showFusionJSON ? 'rgba(184,146,255,0.2)' : 'transparent',
                border: '1px solid var(--border)',
                borderRadius: 4,
                padding: '4px 8px',
                fontSize: 16,
                cursor: 'pointer',
                color: 'var(--text)',
                fontFamily: 'monospace'
              }}
              title="Toggle hexagram JSON view"
            >
              {getIChingCompact((fusion.result as any).iching_hexagram_number as number)}
            </button>
          )}
        </div>
        <div style={{ display: 'flex', gap: 8, position: 'relative' }}>
          {/* Survival mode: Show "?" button when cards selected but not committed */}
          {gameMode === 'survival' && selectedIds.size >= 1 && !fusionCommitted ? (
            <>
              <div style={{ width: 120, height: 120, background: '#2a2a2a', borderRadius: 4, border: '1px solid #3a3a3a', display: 'flex', alignItems: 'center', justifyContent: 'center', position: 'relative' }}>
                <button
                  onClick={commitFusion}
                  className="mono"
                  style={{
                    width: '100%',
                    height: '100%',
                    background: 'rgba(201,120,95,0.1)',
                    border: '2px dashed var(--survival-accent)',
                    borderRadius: 4,
                    color: 'var(--survival-accent)',
                    fontSize: 48,
                    fontWeight: 700,
                    cursor: 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center'
                  }}
                >
                  ?
                </button>
              </div>
              <div style={{ fontSize: 13, flex: 1 }}>
                <div className="mono" style={{ fontWeight: 700 }}>—</div>
                <div style={{ marginBottom: 6 }}>Click "?" to reveal fusion result</div>
                {/* Show score hint */}
                {fusion && (
                  <div style={{ marginTop: 6 }}>
                    <span className="mono" style={{ display: 'inline-block', padding: '6px 10px', borderRadius: 8, background: '#0e639c22', border: '2px solid var(--accent-score)', color: '#d4e7ff', fontWeight: 800, fontSize: 18 }}>
                      <span>Score</span><span style={{ color: 'var(--accent-score)' }}>:</span> {fusion.scoring.totalPoints > 0 ? '> 0' : '== 0'}
                    </span>
                  </div>
                )}
              </div>
            </>
          ) : (
            <>
              {fusion && imageSrc(fusion.result) ? (
                <img src={imageSrc(fusion.result)!} alt={getLocalizedMotifName(fusion.result as unknown as Motif, language)} style={{ width: 120, height: 120, flexShrink: 0, objectFit: 'cover', borderRadius: 4, border: '1px solid #3a3a3a' }} />
              ) : (
                <div style={{ width: 120, height: 120, flexShrink: 0, background: '#2a2a2a', borderRadius: 4, border: '1px solid #3a3a3a' }} />
              )}
              <div style={{ fontSize: 13, flex: 1 }}>
                {showFusionJSON && fusion && (fusion.result as any).iching_hexagram_number !== undefined ? (
                  <HexagramJSONDisplay hexNumber={(fusion.result as any).iching_hexagram_number as number} />
                ) : (
                  <>
                    <div className="mono" style={{ fontWeight: 700, display: 'flex', alignItems: 'center', gap: 6, color: syzygyActive ? '#00ff66' : '#b892ff' }}>
                      <span>{renderWithHighlight(fusion ? (fusion.result as any).id : '—', commonSubstr)}</span>
                      {fusion?.result?.id && (
                        <span style={{ fontSize: 11, opacity: 0.9, color: syzygyActive ? '#00ff66' : undefined }}>DR:{computeCodeReduction((fusion.result as any).id)}</span>
                      )}
                    </div>
                    <div style={{ marginTop: 4, color: 'var(--muted)', fontSize: 18 }}>
                      {fusion && (fusion.result as any).tarot_index !== undefined && renderTarot((fusion.result as any).tarot_index as number)}
                      {fusion && (fusion.result as any).iching_hexagram_number !== undefined && '  '}
                      {fusion && (fusion.result as any).iching_hexagram_number !== undefined && renderIChing((fusion.result as any).iching_hexagram_number as number)}
                    </div>
                    <div style={{ marginTop: 4 }}>{renderWithHighlight(fusion ? getLocalizedMotifName(fusion.result as unknown as Motif, language) : '—', commonSubstr)}</div>
                    
                    <div className="mono" style={{ marginTop: 6, color: 'var(--muted)' }}>Similarity: {fusion ? fusion.similarity.toFixed(3) : '—'}</div>
                    <div style={{ marginTop: 6, display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'nowrap' }}>
                      <span className="mono" style={{ display: 'inline-block', padding: '6px 10px', borderRadius: 8, background: '#0e639c22', border: '2px solid var(--accent-score)', color: '#d4e7ff', fontWeight: 800, fontSize: 18, whiteSpace: 'nowrap' }}>
                        <span>Score</span><span style={{ color: 'var(--accent-score)' }}>:</span> {fusion ? fusion.scoring.totalPoints.toLocaleString() : '0'}
                      </span>
                      {/* Inline Base pill (hidden pre-commit in survival mode) */}
                      {fusion && !(gameMode === 'survival' && !fusionCommitted) && (
                        <span className="mono" style={{ whiteSpace: 'nowrap', fontSize: 12, color: 'var(--muted)', padding: '4px 8px', borderRadius: 9999, border: '1px solid var(--border)', background: 'rgba(255,255,255,0.03)' }}>
                          Base: {fusion.scoring.basePoints.toLocaleString()}
                        </span>
                      )}
                    </div>
                  </>
                )}
              </div>
            </>
          )}
        </div>
        {fusion && (
          <div style={{ marginTop: 8, fontSize: 12 }}>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
              {fusion.scoring.bonuses.length > 0 ? (
                fusion.scoring.bonuses.map((b: any, i: number) => {
                  const isAdd = b.kind === 'additive';
                  let evidence = '';
                  if (Array.isArray(b.evidence) && b.evidence.length > 0) {
                    if (b.type === 'syzygy') {
                      // Syzygy: show pair like "2::7"
                      const pair = b.evidence.find((e: string) => e.includes('::'));
                      evidence = pair ? ` (${pair})` : '';
                    } else if (b.type === 'iching') {
                      // I Ching: show trigram symbol or pair
                      const trigram = b.evidence.find((e: string) => e.startsWith('trigram:'));
                      const pair = b.evidence.find((e: string) => e.startsWith('pair:'));
                      if (trigram) evidence = ` (${trigram.replace('trigram:', '')})`;
                      else if (pair) evidence = ` (${pair.replace('pair:', '')})`;
                    } else {
                      evidence = ` (${b.evidence.slice(0,2).join(', ')})`;
                    }
                  }
                  // Calculate actual points for all bonuses (additive shows points, multipliers show points added)
                  let pointsText = '';
                  if (isAdd) {
                    pointsText = `+${b.additivePoints || 0}`;
                  } else {
                    // For multipliers, calculate points added: base * (multiplier - 1)
                    const basePoints = fusion.scoring.basePoints || 0;
                    const pointsAdded = Math.round(basePoints * ((b.multiplier || 1) - 1));
                    pointsText = `+${pointsAdded}`;
                  }
                  const text = `${pointsText} – ${b.label}${evidence}`;
                  return <BonusBadge key={i} type={b.type} text={text} />;
                })
              ) : (
                <div style={{ color: '#777' }}>No bonuses</div>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Your Hand */}
      <div style={{ border: '1px solid var(--border)', borderRadius: 8, padding: 8, marginBottom: 8, background: 'var(--panel)' }}>
        <div style={{ fontWeight: 600, marginBottom: 8 }}>Your Hand</div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(5, minmax(0, 1fr))', gap: 8 }}>
            {hand?.cards.map(card => {
              const isSelected = selectedIds.has(card.id);
              const selectedCount = selectedIds.size;
              const selectedSingle = isSelected && selectedCount === 1;
              const selectedMulti = isSelected && selectedCount > 1;
              return (
              <button
                key={card.id}
                onClick={() => toggleCard(card.id)}
                title={(() => {
                  const fullMotif = getMotifById(card.id);
                  return fullMotif ? getLocalizedMotifName(fullMotif, language) : card.name;
                })()}
                disabled={gameMode === 'survival' && fusionCommitted}
                style={{
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  justifyContent: 'center',
                  padding: 6,
                border: selectedSingle ? '2px solid #ffffffcc' : (selectedMulti ? '2px solid #89d185' : '1px solid var(--border)'),
                  borderRadius: 8,
                background: isSelected ? '#2a2a2a' : '#252525',
                  minHeight: 120,
                  position: 'relative',
                  cursor: (gameMode === 'survival' && fusionCommitted) ? 'not-allowed' : 'pointer',
                  opacity: (gameMode === 'survival' && fusionCommitted) ? 0.5 : 1
                }}
              >
                {imageSrc(card) ? (
                <img src={imageSrc(card)!} alt={(() => {
                  const fullMotif = getMotifById(card.id);
                  return fullMotif ? getLocalizedMotifName(fullMotif, language) : card.name;
                })()} style={{ width: '100%', borderRadius: 4, border: '1px solid #3a3a3a' }} />
                ) : (
                  <div style={{ width: '100%', height: 80, background: '#f2f2f2', borderRadius: 4 }} />
                )}
               <div className="mono" style={{ fontSize: 12, textAlign: 'center', marginTop: 4, color: '#b892ff' }}>{card.id}</div>
               <div style={{ fontSize: 18, textAlign: 'center', marginTop: 4, color: 'var(--muted)' }}>
                  {card.tarot_index !== undefined && renderTarot(card.tarot_index, false)}
                  {card.iching_hexagram_number !== undefined && '  '}
                  {card.iching_hexagram_number !== undefined && renderIChingSimple(card.iching_hexagram_number)}
                </div>
               <div className="mono" style={{ textAlign: 'center', marginTop: 2, fontSize: 16, fontWeight: 800, color: '#b892ff' }}>{computeCodeReduction(card.id)}</div>
                {selectedMulti && (
                  <div className="mono" style={{ position: 'absolute', top: 6, right: 6, background: '#15331f', color: '#89d185', borderRadius: 6, padding: '2px 6px', fontSize: 10 }}>fuse</div>
                )}
              </button>
            );})}
          </div>
        </div>

      {/* Play Button Panel */}
      {!isDead && (
        <div style={{ border: '1px solid var(--border)', borderRadius: 8, padding: 12, marginBottom: 8, background: 'var(--panel)', display: 'flex', gap: 8, alignItems: 'center' }}>
          <button
            onClick={handlePlay}
            disabled={!fusion || (gameMode === 'survival' && selectedIds.size > 1 && !fusionCommitted)}
            className="mono"
            style={{ 
              flex: 1, 
              height: 52, 
              borderRadius: 8, 
              background: 'var(--panel)', 
              color: (fusion && !(gameMode === 'survival' && selectedIds.size > 1 && !fusionCommitted)) ? 'var(--accent-score)' : 'var(--muted)', 
              border: `1px solid ${(fusion && !(gameMode === 'survival' && selectedIds.size > 1 && !fusionCommitted)) ? 'rgba(79,193,255,0.4)' : 'var(--border)'}`, 
              fontSize: 22, 
              fontWeight: 700,
              cursor: (fusion && !(gameMode === 'survival' && selectedIds.size > 1 && !fusionCommitted)) ? 'pointer' : 'not-allowed',
              opacity: (fusion && !(gameMode === 'survival' && selectedIds.size > 1 && !fusionCommitted)) ? 1 : 0.6,
              transition: 'all 0.2s ease'
            }}
          >
            Play and Score
          </button>
          <OverflowMenu onReset={onReset} onSubmit={onSubmitScore} />
        </div>
      )}

      {/* Name Entry Dialog (shows first when dead) */}
      {isDead && survivalResult && showNameEntry && (
        <NameEntryDialog
          isOpen={true}
          onSubmit={handleSubmitHighScore}
          onSkip={() => setShowNameEntry(false)}
        />
      )}

      {/* Death Screen */}
      {isDead && survivalResult && !showNameEntry && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000, padding: 16 }}>
          <div style={{ background: 'var(--panel)', color: 'var(--text)', border: '1px solid var(--border)', borderRadius: 12, padding: 20, maxWidth: 400, width: '100%' }}>
            <h3 style={{ margin: '0 0 16px 0', color: 'var(--error)', fontSize: 24 }}>Game Over</h3>
            <div style={{ fontSize: 14, lineHeight: 1.8 }}>
              <div><strong>Rounds Survived:</strong> {survivalResult.roundsSurvived}</div>
              <div><strong>Total Score:</strong> {survivalResult.totalScore.toLocaleString()}</div>
              <div><strong>Average Score:</strong> {survivalResult.averageScore.toFixed(1)}</div>
              <div><strong>Best Single Score:</strong> {survivalResult.maxSingleScore.toLocaleString()}</div>
              <div style={{ marginTop: 16, paddingTop: 16, borderTop: '1px solid var(--border)' }}>
                <button
                  onClick={() => setShowNameEntry(true)}
                  className="mono"
                  disabled={submittingScore || scoreSubmitted}
                  style={{
                    width: '100%',
                    padding: '12px',
                    background: scoreSubmitted ? 'var(--muted)' : 'var(--accent-score)',
                    color: '#fff',
                    border: 'none',
                    borderRadius: 8,
                    fontSize: 16,
                    fontWeight: 700,
                    cursor: (submittingScore || scoreSubmitted) ? 'not-allowed' : 'pointer',
                    opacity: (submittingScore || scoreSubmitted) ? 0.6 : 1,
                    marginTop: 8,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    gap: 8
                  }}
                >
                  {submittingScore ? 'Submitting...' : scoreSubmitted ? (
                    <>
                      <span>✓</span>
                      <span>Score Submitted</span>
                    </>
                  ) : 'Submit High Score'}
                </button>
                <button
                  onClick={handlePlayAgain}
                  className="mono"
                  style={{
                    width: '100%',
                    padding: '12px',
                    background: 'var(--survival-accent)',
                    color: '#fff',
                    border: 'none',
                    borderRadius: 8,
                    fontSize: 16,
                    fontWeight: 700,
                    cursor: 'pointer',
                    marginTop: 8
                  }}
                >
                  Play Again
                </button>
                <button
                  onClick={() => {
                    handlePlayAgain();
                    toggleMode(); // Switch back to practice mode
                  }}
                  className="mono"
                  style={{
                    width: '100%',
                    padding: '12px',
                    background: 'transparent',
                    color: 'var(--text)',
                    border: '1px solid var(--border)',
                    borderRadius: 8,
                    fontSize: 14,
                    fontWeight: 600,
                    cursor: 'pointer',
                    marginTop: 8
                  }}
                >
                  Back to Practice
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* High Scores Dialog */}
      <HighScoresDialog isOpen={highScoresOpen} onClose={() => setHighScoresOpen(false)} />

      {/* Share Dialog */}
      {shareOpen && (
        <div role="dialog" aria-modal="true" style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.35)', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 16 }} onClick={() => setShareOpen(false)}>
          <div style={{ background: 'var(--panel)', color: 'var(--text)', border: '1px solid var(--border)', width: '100%', maxWidth: 420, borderRadius: 12, padding: 16 }} onClick={e => e.stopPropagation()}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
              <h3 style={{ margin: 0 }}>Share</h3>
              <button onClick={() => setShareOpen(false)} style={{ border: '1px solid var(--border)', color: 'var(--text)', borderRadius: 6, background: 'var(--panel)', height: 28, padding: '0 10px' }}>Close</button>
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 12 }}>
              <img
                src={qrUrlResolved}
                alt="Game QR code"
                style={{ width: '100%', maxWidth: 300, height: 'auto', borderRadius: 8, border: '1px solid var(--border)', background: '#fff' }}
              />
            </div>
          </div>
        </div>
      )}

      {/* Help Modal */}
      {helpOpen && (
        <div role="dialog" aria-modal="true" style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.35)', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '16px' }} onClick={() => setHelpOpen(false)}>
          <div style={{ background: 'var(--panel)', color: 'var(--text)', border: '1px solid var(--border)', width: '100%', maxWidth: 520, borderRadius: 12, padding: 16, maxHeight: '85vh', overflow: 'auto' }} onClick={e => e.stopPropagation()}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
              <h3 style={{ margin: 0 }}>Help</h3>
              <button onClick={() => setHelpOpen(false)} style={{ border: '1px solid var(--border)', color: 'var(--text)', borderRadius: 6, background: 'var(--panel)', height: 28, padding: '0 10px' }}>Close</button>
            </div>
            
            <div style={{ fontSize: 13, color: 'var(--text)', lineHeight: '1.6' }}>
              <div style={{ marginBottom: 20 }}>
                <h4 style={{ margin: '0 0 8px 0', fontSize: 15, fontWeight: 600 }}>What are these things?</h4>
                <p style={{ margin: 0 }}>
                  The motifs you're playing with come from the <strong>Thompson Motif Index</strong>, a comprehensive classification system for narrative elements in folktales, myths, and legends. Each motif represents a recurring theme, character, or plot element found across different cultural stories.
                </p>
                <p style={{ margin: '8px 0 0 0' }}>
                  This dataset is based on the <a href="https://github.com/j-hagedorn/trilogy" target="_blank" rel="noopener noreferrer" style={{ color: 'var(--accent-score)', textDecoration: 'underline' }}>trilogy repository</a> by Joshua Hagedorn. Learn more about the <a href="https://en.wikipedia.org/wiki/Motif-Index_of_Folk-Literature" target="_blank" rel="noopener noreferrer" style={{ color: 'var(--accent-score)', textDecoration: 'underline' }}>Thompson Motif Index on Wikipedia</a>.
                </p>
              </div>

              <div style={{ marginBottom: 20 }}>
                <h4 style={{ margin: '0 0 8px 0', fontSize: 15, fontWeight: 600 }}>How to play?</h4>
                <p style={{ margin: 0 }}>
                  Your goal is to combine motifs from your hand to get as close as possible to the target motif. Tap cards to select them. If you select one card, it's used directly. If you select multiple cards, they're fused by averaging their embeddings, and the nearest matching motif is found (excluding the cards you selected).
                </p>
                <p style={{ margin: '8px 0 0 0' }}>
                  Different types of matches increase your score:
                </p>
                <ul style={{ margin: '8px 0 0 20px', padding: 0 }}>
                  <li>Base similarity to the target</li>
                  <li>Matching Tarot cards</li>
                  <li>Matching I Ching hexagrams</li>
                  <li>Shared words in titles</li>
                  <li>Same chapter classification</li>
                  <li>Digital Reduction (DR) match: +99 points</li>
                </ul>
                <p style={{ margin: '8px 0 0 0' }}>
                  Try different combinations to discover ways to maximize your score!
                </p>
              </div>

              <div style={{ marginBottom: 20, paddingTop: 16, borderTop: '1px solid var(--border)' }}>
                <h4 style={{ margin: '0 0 8px 0', fontSize: 15, fontWeight: 600 }}>Survival mode</h4>
                <p style={{ margin: 0 }}>
                  Survival mode adds challenge by hiding fusion results until you commit. Here's how it works:
                </p>
                <ul style={{ margin: '8px 0 0 20px', padding: 0 }}>
                  <li>Select cards from your hand (single or multiple)</li>
                  <li>See a hint: "Score: &gt; 0" or "Score: == 0" and bonus multipliers</li>
                  <li>Click the "?" button to reveal the exact fusion result and score</li>
                  <li>Click "Play and Score" to add points to your life and continue</li>
                </ul>
                <p style={{ margin: '8px 0 0 0' }}>
                  Each round, damage increases and is deducted from your life. If your life drops below zero, the game ends. Your goal is to survive as many rounds as possible by scoring well!
                </p>
                <p style={{ margin: '8px 0 0 0', fontSize: 12, color: 'var(--muted)' }}>
                  Tip: The bonuses are always visible before committing, so you can strategize which combinations will work best.
                </p>
              </div>

              <div style={{ marginBottom: 0, paddingTop: 16, borderTop: '1px solid var(--border)' }}>
                <h4 style={{ margin: '0 0 8px 0', fontSize: 15, fontWeight: 600 }}>Dataset Information</h4>
                <div style={{ fontSize: 12, color: 'var(--muted)', lineHeight: '1.8' }}>
                  <div>Total motifs: <strong style={{ color: 'var(--text)' }}>{motifs.length}</strong></div>
                  <div>Embedding dimension: <strong style={{ color: 'var(--text)' }}>{motifs[0]?.embedding?.length || 'N/A'}</strong></div>
                  <div>I Ching hexagrams covered: <strong style={{ color: 'var(--text)' }}>{uniqueIChing.size}</strong> / 64</div>
                  <div style={{ marginTop: 8 }}>
                    <strong style={{ color: 'var(--text)' }}>Digital Reduction (DR):</strong> We compute DR by summing the ASCII codes of a motif's ID and taking the base-10 digital root (1–9; 0 stays 0). When your card and the target share the same DR, you gain an additional +99 points.
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const btnStyle: React.CSSProperties = {
  padding: '10px 12px',
  borderRadius: 8,
  background: 'var(--play)',
  color: '#fff',
  border: 'none'
};

const btnStyleAlt: React.CSSProperties = {
  ...btnStyle,
  background: '#555'
};

function BonusBadge(props: { type: 'tarot' | 'iching' | 'title' | 'chapter' | 'code' | 'substring' | 'syzygy'; text: string }) {
  // Dynamic coloring to keep descriptors consistent with glyph highlights
  const isHexagram = props.type === 'iching' && /hexagram/i.test(props.text);
  const isTarotFullMatch = props.type === 'tarot' && /\(both\)/i.test(props.text);
  const color = props.type === 'tarot' ? (isTarotFullMatch
      ? { bg: 'rgba(255,215,106,0.18)', fg: '#ffd76a' } // full tarot match gold/yellow
      : { bg: 'rgba(210,59,59,0.15)', fg: '#d23b3b' }) // tarot partial matches in red
    : props.type === 'iching' ? (isHexagram
      ? { bg: 'rgba(255,215,106,0.18)', fg: '#ffd76a' } // hexagram badges gold/yellow
      : { bg: 'rgba(210,59,59,0.15)', fg: '#d23b3b' }) // trigram badges red
    : props.type === 'title' ? { bg: 'var(--pill-title-bg)', fg: 'var(--pill-title-fg)' }
    : props.type === 'code' ? { bg: 'rgba(184,146,255,0.15)', fg: '#b892ff' }
    : props.type === 'substring' ? { bg: 'rgba(79,193,255,0.12)', fg: 'var(--accent-score)' }
    : props.type === 'syzygy' ? { bg: '#000000', fg: '#00ff66' }
    : { bg: 'var(--pill-chapter-bg)', fg: 'var(--pill-chapter-fg)' };
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '4px 8px', borderRadius: 10, background: color.bg, border: `1px solid ${color.fg}22`, fontSize: 11 }}>
      <span style={{ width: 6, height: 6, borderRadius: 6, background: color.fg, display: 'inline-block' }} />
      <span style={{ color: color.fg }}>{props.text}</span>
    </span>
  );
}

function OverflowMenu(props: { onReset: () => void; onSubmit: () => void }) {
  const [open, setOpen] = React.useState(false);
  return (
    <div style={{ position: 'relative' }}>
      <button aria-label="More" onClick={() => setOpen(o => !o)} style={{ width: 52, height: 52, borderRadius: 8, border: '1px solid var(--border)', background: 'var(--panel)', color: 'var(--text)' }}>⋯</button>
      {open && (
        <div style={{ position: 'absolute', bottom: 56, right: 0, background: 'var(--panel)', color: 'var(--text)', border: '1px solid var(--border)', borderRadius: 8, padding: 8, minWidth: 160, boxShadow: '0 4px 12px rgba(0,0,0,0.3)' }}>
          <button onClick={() => { props.onReset(); setOpen(false); }} style={{ display: 'block', width: '100%', textAlign: 'left', padding: 8, background: 'transparent', border: 'none', color: 'var(--text)' }}>Reset</button>
          <button onClick={() => { props.onSubmit(); setOpen(false); }} style={{ display: 'block', width: '100%', textAlign: 'left', padding: 8, background: 'transparent', border: 'none', color: 'var(--text)' }}>Submit score (stub)</button>
        </div>
      )}
    </div>
  );
}


