import { Motif } from '../types/motif';
import { Language } from './languageContext';

/**
 * Get the localized name for a motif based on the current language.
 * Falls back to the default 'name' field if translation is not available.
 */
export function getLocalizedMotifName(motif: Motif, language: Language): string {
  if (language === 'pt_br' && motif.name_pt_br) {
    return motif.name_pt_br;
  }
  // Default to English name
  return motif.name;
}

