import React, { useEffect, useState } from 'react';
import { getHighScores, HighScoreEntry } from '../utils/googleSheets';

interface HighScoresDialogProps {
  isOpen: boolean;
  onClose: () => void;
}

export default function HighScoresDialog({ isOpen, onClose }: HighScoresDialogProps): React.ReactElement | null {
  const [scores, setScores] = useState<HighScoreEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (isOpen) {
      setLoading(true);
      setError(null);
      getHighScores(50)
        .then((data) => {
          setScores(data);
          setLoading(false);
        })
        .catch((err) => {
          console.error('Failed to load high scores:', err);
          setError('Failed to load high scores');
          setLoading(false);
        });
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const formatDate = (isoString: string): string => {
    try {
      const date = new Date(isoString);
      return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
    } catch {
      return isoString;
    }
  };

  return (
    <div
      role="dialog"
      aria-modal="true"
      style={{
        position: 'fixed',
        inset: 0,
        background: 'rgba(0,0,0,0.7)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        zIndex: 1000,
        padding: 16,
      }}
      onClick={(e) => {
        if (e.target === e.currentTarget) {
          onClose();
        }
      }}
    >
      <div
        style={{
          background: 'var(--panel)',
          color: 'var(--text)',
          border: '1px solid var(--border)',
          borderRadius: 12,
          padding: 20,
          maxWidth: 600,
          width: '100%',
          maxHeight: '85vh',
          overflow: 'auto',
        }}
        onClick={(e) => e.stopPropagation()}
      >
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
          <h3 style={{ margin: 0 }}>High Scores</h3>
          <button
            onClick={onClose}
            style={{
              border: '1px solid var(--border)',
              color: 'var(--text)',
              borderRadius: 6,
              background: 'var(--panel)',
              height: 28,
              padding: '0 10px',
              cursor: 'pointer',
            }}
          >
            Close
          </button>
        </div>

        {loading ? (
          <div style={{ textAlign: 'center', padding: 40, color: 'var(--muted)' }}>Loading high scores...</div>
        ) : error ? (
          <div style={{ textAlign: 'center', padding: 40, color: 'var(--error)' }}>{error}</div>
        ) : scores.length === 0 ? (
          <div style={{ textAlign: 'center', padding: 40, color: 'var(--muted)' }}>No high scores yet. Be the first!</div>
        ) : (
          <div style={{ overflowX: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 13 }}>
              <thead>
                <tr style={{ borderBottom: '1px solid var(--border)' }}>
                  <th style={{ textAlign: 'left', padding: '8px 12px', fontWeight: 600, color: 'var(--muted)' }}>Rank</th>
                  <th style={{ textAlign: 'left', padding: '8px 12px', fontWeight: 600, color: 'var(--muted)' }}>Name</th>
                  <th style={{ textAlign: 'right', padding: '8px 12px', fontWeight: 600, color: 'var(--muted)' }}>Rounds</th>
                  <th style={{ textAlign: 'right', padding: '8px 12px', fontWeight: 600, color: 'var(--muted)' }}>Total Score</th>
                  <th style={{ textAlign: 'right', padding: '8px 12px', fontWeight: 600, color: 'var(--muted)' }}>Avg Score</th>
                  <th style={{ textAlign: 'right', padding: '8px 12px', fontWeight: 600, color: 'var(--muted)' }}>Date</th>
                </tr>
              </thead>
              <tbody>
                {scores.map((score, index) => (
                  <tr key={index} style={{ borderBottom: '1px solid var(--border)' }}>
                    <td style={{ padding: '8px 12px', fontWeight: 700 }}>#{index + 1}</td>
                    <td style={{ padding: '8px 12px' }}>{score.name || 'Anonymous'}</td>
                    <td style={{ padding: '8px 12px', textAlign: 'right' }} className="mono">
                      {score.roundsSurvived.toLocaleString()}
                    </td>
                    <td style={{ padding: '8px 12px', textAlign: 'right' }} className="mono">
                      {score.totalScore.toLocaleString()}
                    </td>
                    <td style={{ padding: '8px 12px', textAlign: 'right' }} className="mono">
                      {score.averageScore.toFixed(1)}
                    </td>
                    <td style={{ padding: '8px 12px', textAlign: 'right', color: 'var(--muted)', fontSize: 12 }}>
                      {formatDate(score.playedAt)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

