import React, { useState } from 'react';

interface NameEntryDialogProps {
  isOpen: boolean;
  onSubmit: (name: string) => void;
  onSkip: () => void;
}

export default function NameEntryDialog({ isOpen, onSubmit, onSkip }: NameEntryDialogProps): React.ReactElement | null {
  const [name, setName] = useState('');

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmedName = name.trim();
    if (trimmedName.length > 0) {
      onSubmit(trimmedName.substring(0, 64));
    }
  };

  return (
    <div
      role="dialog"
      aria-modal="true"
      style={{
        position: 'fixed',
        inset: 0,
        background: 'rgba(0,0,0,0.7)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        zIndex: 1001,
        padding: 16,
      }}
      onClick={(e) => {
        if (e.target === e.currentTarget) {
          onSkip();
        }
      }}
    >
      <div
        style={{
          background: 'var(--panel)',
          color: 'var(--text)',
          border: '1px solid var(--border)',
          borderRadius: 12,
          padding: 20,
          maxWidth: 400,
          width: '100%',
        }}
        onClick={(e) => e.stopPropagation()}
      >
        <h3 style={{ margin: '0 0 16px 0', fontSize: 18 }}>Submit High Score</h3>
        <p style={{ margin: '0 0 16px 0', fontSize: 13, color: 'var(--muted)' }}>
          Enter your name to appear on the leaderboard (optional)
        </p>
        <form onSubmit={handleSubmit}>
          <input
            type="text"
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="Your name"
            maxLength={64}
            className="mono"
            style={{
              width: '100%',
              padding: '10px 12px',
              borderRadius: 8,
              background: 'var(--bg)',
              border: '1px solid var(--border)',
              color: 'var(--text)',
              fontSize: 14,
              marginBottom: 16,
              boxSizing: 'border-box',
            }}
            autoFocus
          />
          <div style={{ display: 'flex', gap: 8 }}>
            <button
              type="button"
              onClick={onSkip}
              className="mono"
              style={{
                flex: 1,
                padding: '10px',
                background: 'transparent',
                color: 'var(--text)',
                border: '1px solid var(--border)',
                borderRadius: 8,
                fontSize: 14,
                fontWeight: 600,
                cursor: 'pointer',
              }}
            >
              Skip
            </button>
            <button
              type="submit"
              className="mono"
              style={{
                flex: 1,
                padding: '10px',
                background: 'var(--accent-score)',
                color: '#fff',
                border: 'none',
                borderRadius: 8,
                fontSize: 14,
                fontWeight: 700,
                cursor: 'pointer',
              }}
              disabled={name.trim().length === 0}
            >
              Submit
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

