/**
 * Google Sheets API client via Apps Script proxy
 * 
 * This calls a Google Apps Script web app that securely handles
 * authentication with the service account.
 */

const APPS_SCRIPT_URL = process.env.REACT_APP_APPS_SCRIPT_URL || '';

export interface HighScoreEntry {
  name: string;
  roundsSurvived: number;
  totalScore: number;
  averageScore: number;
  maxSingleScore: number;
  playedAt: string;
}

export interface SubmitHighScoreData {
  name: string;
  roundsSurvived: number;
  totalScore: number;
  averageScore: number;
  maxSingleScore: number;
  playedAt: string;
}

export interface HighScoresResponse {
  success: boolean;
  scores?: HighScoreEntry[];
  error?: string;
}

export interface SubmitResponse {
  success: boolean;
  error?: string;
}

/**
 * Submit a high score to the leaderboard
 */
export async function submitHighScore(data: SubmitHighScoreData): Promise<SubmitResponse> {
  if (!APPS_SCRIPT_URL) {
    console.error('REACT_APP_APPS_SCRIPT_URL not configured');
    return { success: false, error: 'High scores service not configured' };
  }

  try {
    // Use GET request with query params to avoid CORS issues entirely
    // Apps Script handles GET requests without CORS preflight
    const params = new URLSearchParams({
      action: 'submit',
      name: data.name || 'Anonymous',
      roundsSurvived: String(data.roundsSurvived || 0),
      totalScore: String(data.totalScore || 0),
      averageScore: String(data.averageScore || 0),
      maxSingleScore: String(data.maxSingleScore || 0),
      playedAt: data.playedAt || new Date().toISOString(),
    });
    
    const url = `${APPS_SCRIPT_URL}?${params.toString()}`;
    const response = await fetch(url, {
      method: 'GET',
      mode: 'cors', // GET requests work with CORS
    });

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const result = await response.json();
    return result;
  } catch (error) {
    console.error('Error submitting high score:', error);
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Failed to submit high score',
    };
  }
}

/**
 * Retrieve high scores from the leaderboard
 */
export async function getHighScores(limit: number = 50): Promise<HighScoreEntry[]> {
  if (!APPS_SCRIPT_URL) {
    console.error('REACT_APP_APPS_SCRIPT_URL not configured');
    return [];
  }

  try {
    const url = `${APPS_SCRIPT_URL}?limit=${limit}`;
    const response = await fetch(url, {
      method: 'GET',
    });

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const result: HighScoresResponse = await response.json();
    if (result.success && result.scores) {
      return result.scores;
    } else {
      console.error('Error retrieving high scores:', result.error);
      return [];
    }
  } catch (error) {
    console.error('Error retrieving high scores:', error);
    return [];
  }
}

